import Navbar from "../components/Navbar";
import Footer from "../components/Footer";
import FeatureCard from "../components/FeatureCard";

export default function Home() {
  return (
    <>
      <Navbar />

      <main className="bg-gradient-to-b from-blue-50 via-white to-white">

        {/* HERO */}
        <section className="pt-28 sm:pt-36 pb-20 sm:pb-28">
          <div className="max-w-3xl mx-auto px-4 text-center">
            <h1 className="text-3xl sm:text-5xl md:text-6xl font-semibold leading-tight mb-6">
              A safe place for everything that matters.
            </h1>

            <p className="text-gray-600 text-base sm:text-lg max-w-xl mx-auto mb-8">
              Store your photos, videos, and documents securely.
              Access them anytime, from any device.
            </p>

            <div className="flex flex-col sm:flex-row gap-3 sm:gap-4 justify-center">
              <a
                href="/signup"
                className="bg-blue-600 text-white px-8 py-3.5 rounded-xl font-medium text-center"
              >
                Get started — Free 5GB
              </a>
              <a
                href="/login"
                className="px-8 py-3.5 rounded-xl border border-gray-300 text-center"
              >
                Login
              </a>
            </div>

            <p className="text-xs text-gray-500 mt-4">
              No credit card required
            </p>
          </div>
        </section>

        {/* PRODUCT PREVIEW — VIDEO-LIKE DEMO */}
<section className="relative pb-20 sm:pb-28 -mt-6 sm:-mt-10 overflow-hidden">
  <div className="absolute inset-0 bg-gradient-to-b from-transparent via-blue-50/40 to-transparent" />

  <div className="relative max-w-5xl mx-auto px-4">
    <div className="relative rounded-2xl bg-white shadow-md border border-gray-100 p-4 sm:p-6 overflow-hidden">

      {/* Fake browser bar */}
      <div className="flex items-center gap-2 mb-6">
        <div className="w-3 h-3 rounded-full bg-gray-200" />
        <div className="w-3 h-3 rounded-full bg-gray-200" />
        <div className="w-3 h-3 rounded-full bg-gray-200" />
      </div>

      {/* App body */}
      <div className="relative space-y-4">

        {/* Upload button */}
        <div className="inline-block bg-blue-600 text-white text-sm px-4 py-2 rounded-lg upload-btn">
          Upload file
        </div>

        {/* Fake file rows */}
        <div className="space-y-3 mt-6">
          <div className="h-4 bg-gray-100 rounded w-3/4" />
          <div className="h-4 bg-gray-100 rounded w-2/3" />
          <div className="h-4 bg-gray-100 rounded w-1/2" />
        </div>

        {/* Status text */}
        <p className="text-sm text-green-600 mt-6 opacity-0 status-text">
          Files securely uploaded to your vault
        </p>

        {/* Fake cursor */}
        <div className="fake-cursor" />

      </div>
    </div>
  </div>

  {/* Animation styles */}
  <style>{`
    .fake-cursor {
      position: absolute;
      top: 120px;
      left: 40px;
      width: 18px;
      height: 18px;
      border-radius: 50%;
      background: #111;
      opacity: 0;
      animation: cursor-move 7s infinite;
    }

    .upload-btn {
      position: relative;
      animation: button-pulse 7s infinite;
    }

    .status-text {
      animation: status-show 7s infinite;
    }

    @keyframes cursor-move {
      0% {
        opacity: 0;
        transform: translate(0, 0);
      }
      10% {
        opacity: 1;
      }
      30% {
        transform: translate(0, 0);
      }
      45% {
        transform: translate(120px, 0);
      }
      50% {
        transform: translate(120px, 0) scale(0.9);
      }
      55% {
        transform: translate(120px, 0) scale(1);
      }
      80% {
        opacity: 1;
      }
      100% {
        opacity: 0;
      }
    }

    @keyframes button-pulse {
      0%, 40% {
        box-shadow: none;
      }
      50% {
        box-shadow: 0 0 0 6px rgba(37, 99, 235, 0.15);
      }
      60% {
        box-shadow: none;
      }
    }

    @keyframes status-show {
      0%, 55% {
        opacity: 0;
      }
      65% {
        opacity: 1;
      }
      90% {
        opacity: 1;
      }
      100% {
        opacity: 0;
      }
    }
  `}</style>
</section>



        {/* VALUE STATEMENTS */}
{/* VALUE STATEMENTS — PRODUCT ALIGNED */}
<section className="pb-20 sm:pb-28">
  <div className="max-w-5xl mx-auto px-4">

    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm">

      <div className="grid grid-cols-1 sm:grid-cols-3 divide-y sm:divide-y-0 sm:divide-x">

        <div className="p-6 sm:p-8">
          <p className="text-sm text-gray-500 mb-2">
            Privacy
          </p>
          <p className="text-base sm:text-lg text-gray-800">
            Your files stay private by default.
          </p>
